import { rateOn, showDue, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { useSelectedClaims } from '../bulk/useSelectedClaims';
import {
  AMOUNT,
  CLAIM_NUMBER,
  claimDueCents,
  claimed,
  claimsKey,
  isOpen,
  live,
  overdue,
  overdueFigures,
  personDueCents,
  capCents,
